import logging
import uuid

class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock

    def place_order(self, user: str, item: str, quantity: int, is_admin: bool = False) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            reservation_id = self.stock.reserve(item, quantity)
            return 200, f"Order placed successfully. Reservation ID: {reservation_id}"
        except Exception as e:
            error_code = str(uuid.uuid4())
            logging.error(f"Error {error_code}: {e}", exc_info=True)
            if is_admin:
                return 500, f"Unexpected error {error_code}: {type(e).__name__}: {str(e)}"
            else:
                return 500, f"Unexpected error {error_code}. Please contact the administrator for more information."

# Example usage:
if __name__ == "__main__":
    class MockStock:
        def reserve(self, item: str, quantity: int) -> int:
            # Simulate a successful reservation
            return 123

    stock = MockStock()
    order_service = OrderService(stock)
    print(order_service.place_order("user1", "item1", 1))

    class FailingMockStock:
        def reserve(self, item: str, quantity: int) -> int:
            # Simulate an unexpected error
            raise Exception("Mock error")

    stock = FailingMockStock()
    order_service = OrderService(stock)
    print(order_service.place_order("user1", "item1", 1))
    print(order_service.place_order("admin1", "item1", 1, is_admin=True))
